/// <reference lib="webworker" />
// Browser/Wasm execution stays off the main thread.
export const openDirectLixBinding = undefined;
export function createWorkerConnection() {
    const worker = new Worker(new URL("./entry.browser.js", import.meta.url), {
        type: "module",
        name: "lix",
    });
    return {
        postMessage(message) {
            worker.postMessage(message);
        },
        onMessage(listener) {
            worker.onmessage = (event) => listener(event.data);
        },
        onFatal(listener) {
            worker.onerror = (event) => listener(event.error ?? new Error(event.message ?? "Lix worker failed"));
        },
        ref() { },
        unref() { },
        async terminate() {
            worker.terminate();
        },
    };
}
